namespace SoloDatabase

open System.Text
open NativeSQLiteTools

/// Persistent row event definitions share the established schema initialization owner.
module internal FileSystemEventSchema =
    let private definitionsByTable = [|
        "SoloDBFileHeader", """
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileHeader_BEFORE_INSERT BEFORE INSERT ON SoloDBFileHeader FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(0) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(0, NEW.FullPath, NEW.Name, NEW.Length, NEW.Created, NEW.Modified, NEW.FullPath, NEW.Name, NEW.Length, NEW.Created, NEW.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(0) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileHeader_AFTER_INSERT AFTER INSERT ON SoloDBFileHeader FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(1) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(1, NEW.FullPath, NEW.Name, NEW.Length, NEW.Created, NEW.Modified, NEW.FullPath, NEW.Name, NEW.Length, NEW.Created, NEW.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(1) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileHeader_BEFORE_DELETE BEFORE DELETE ON SoloDBFileHeader FOR EACH ROW  BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(2, OLD.FullPath, OLD.Name, OLD.Length, OLD.Created, OLD.Modified, OLD.FullPath, OLD.Name, OLD.Length, OLD.Created, OLD.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(2) = 1;
SELECT SOLO_FS_DELETING_BEGIN(OLD.Id, 0, OLD.FullPath); END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileHeader_AFTER_DELETE AFTER DELETE ON SoloDBFileHeader FOR EACH ROW  BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(3, OLD.FullPath, OLD.Name, OLD.Length, OLD.Created, OLD.Modified, OLD.FullPath, OLD.Name, OLD.Length, OLD.Created, OLD.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(3) = 1;
SELECT SOLO_FS_DELETING_END(OLD.Id, 0); END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileHeader_BEFORE_UPDATE BEFORE UPDATE ON SoloDBFileHeader FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(4) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(4, OLD.FullPath, OLD.Name, OLD.Length, OLD.Created, OLD.Modified, NEW.FullPath, NEW.Name, NEW.Length, NEW.Created, NEW.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(4) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileHeader_AFTER_UPDATE AFTER UPDATE ON SoloDBFileHeader FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(5) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(5, OLD.FullPath, OLD.Name, OLD.Length, OLD.Created, OLD.Modified, NEW.FullPath, NEW.Name, NEW.Length, NEW.Created, NEW.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(5) = 1; END;
"""
        "SoloDBDirectoryHeader", """
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryHeader_BEFORE_INSERT BEFORE INSERT ON SoloDBDirectoryHeader FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(6) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(6, NEW.FullPath, NEW.Name, 0, NEW.Created, NEW.Modified, NEW.FullPath, NEW.Name, 0, NEW.Created, NEW.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(6) = 1; END;
