CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryHeader_BEFORE_DELETE BEFORE DELETE ON SoloDBDirectoryHeader FOR EACH ROW  BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(8, OLD.FullPath, OLD.Name, 0, OLD.Created, OLD.Modified, OLD.FullPath, OLD.Name, 0, OLD.Created, OLD.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(8) = 1;
SELECT SOLO_FS_DELETING_BEGIN(OLD.Id, 1, OLD.FullPath); END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryHeader_AFTER_DELETE AFTER DELETE ON SoloDBDirectoryHeader FOR EACH ROW  BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(9, OLD.FullPath, OLD.Name, 0, OLD.Created, OLD.Modified, OLD.FullPath, OLD.Name, 0, OLD.Created, OLD.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(9) = 1;
SELECT SOLO_FS_DELETING_END(OLD.Id, 1); END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryHeader_BEFORE_UPDATE BEFORE UPDATE ON SoloDBDirectoryHeader FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(10) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(10, OLD.FullPath, OLD.Name, 0, OLD.Created, OLD.Modified, NEW.FullPath, NEW.Name, 0, NEW.Created, NEW.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(10) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryHeader_AFTER_UPDATE AFTER UPDATE ON SoloDBDirectoryHeader FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(11) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_ROW(11, OLD.FullPath, OLD.Name, 0, OLD.Created, OLD.Modified, NEW.FullPath, NEW.Name, 0, NEW.Created, NEW.Modified) AS message) WHERE SOLO_FS_SHOULD_HANDLE(11) = 1; END;
"""
        "SoloDBFileMetadata", """
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileMetadata_BEFORE_INSERT BEFORE INSERT ON SoloDBFileMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(12) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(12, COALESCE((SELECT FullPath FROM SoloDBFileHeader WHERE Id = NEW.FileId), SOLO_FS_DELETING_PATH(NEW.FileId, 0)), NEW.Key, NULL, NEW.Value, 0) AS message) WHERE SOLO_FS_SHOULD_HANDLE(12) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileMetadata_AFTER_INSERT AFTER INSERT ON SoloDBFileMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(13) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(13, COALESCE((SELECT FullPath FROM SoloDBFileHeader WHERE Id = NEW.FileId), SOLO_FS_DELETING_PATH(NEW.FileId, 0)), NEW.Key, NULL, NEW.Value, 0) AS message) WHERE SOLO_FS_SHOULD_HANDLE(13) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileMetadata_BEFORE_DELETE BEFORE DELETE ON SoloDBFileMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(12) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(12, COALESCE((SELECT FullPath FROM SoloDBFileHeader WHERE Id = OLD.FileId), SOLO_FS_DELETING_PATH(OLD.FileId, 0)), OLD.Key, OLD.Value, NULL, 1) AS message) WHERE SOLO_FS_SHOULD_HANDLE(12) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileMetadata_AFTER_DELETE AFTER DELETE ON SoloDBFileMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(13) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(13, COALESCE((SELECT FullPath FROM SoloDBFileHeader WHERE Id = OLD.FileId), SOLO_FS_DELETING_PATH(OLD.FileId, 0)), OLD.Key, OLD.Value, NULL, 1) AS message) WHERE SOLO_FS_SHOULD_HANDLE(13) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileMetadata_BEFORE_UPDATE BEFORE UPDATE ON SoloDBFileMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(12) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(12, COALESCE((SELECT FullPath FROM SoloDBFileHeader WHERE Id = NEW.FileId), SOLO_FS_DELETING_PATH(NEW.FileId, 0)), NEW.Key, OLD.Value, NEW.Value, 2) AS message) WHERE SOLO_FS_SHOULD_HANDLE(12) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBFileMetadata_AFTER_UPDATE AFTER UPDATE ON SoloDBFileMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(13) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(13, COALESCE((SELECT FullPath FROM SoloDBFileHeader WHERE Id = NEW.FileId), SOLO_FS_DELETING_PATH(NEW.FileId, 0)), NEW.Key, OLD.Value, NEW.Value, 2) AS message) WHERE SOLO_FS_SHOULD_HANDLE(13) = 1; END;
"""
        "SoloDBDirectoryMetadata", """
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryMetadata_BEFORE_INSERT BEFORE INSERT ON SoloDBDirectoryMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(14) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(14, COALESCE((SELECT FullPath FROM SoloDBDirectoryHeader WHERE Id = NEW.DirectoryId), SOLO_FS_DELETING_PATH(NEW.DirectoryId, 1)), NEW.Key, NULL, NEW.Value, 0) AS message) WHERE SOLO_FS_SHOULD_HANDLE(14) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryMetadata_AFTER_INSERT AFTER INSERT ON SoloDBDirectoryMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(15) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(15, COALESCE((SELECT FullPath FROM SoloDBDirectoryHeader WHERE Id = NEW.DirectoryId), SOLO_FS_DELETING_PATH(NEW.DirectoryId, 1)), NEW.Key, NULL, NEW.Value, 0) AS message) WHERE SOLO_FS_SHOULD_HANDLE(15) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryMetadata_BEFORE_DELETE BEFORE DELETE ON SoloDBDirectoryMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(14) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(14, COALESCE((SELECT FullPath FROM SoloDBDirectoryHeader WHERE Id = OLD.DirectoryId), SOLO_FS_DELETING_PATH(OLD.DirectoryId, 1)), OLD.Key, OLD.Value, NULL, 1) AS message) WHERE SOLO_FS_SHOULD_HANDLE(14) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryMetadata_AFTER_DELETE AFTER DELETE ON SoloDBDirectoryMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(15) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(15, COALESCE((SELECT FullPath FROM SoloDBDirectoryHeader WHERE Id = OLD.DirectoryId), SOLO_FS_DELETING_PATH(OLD.DirectoryId, 1)), OLD.Key, OLD.Value, NULL, 1) AS message) WHERE SOLO_FS_SHOULD_HANDLE(15) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryMetadata_BEFORE_UPDATE BEFORE UPDATE ON SoloDBDirectoryMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(14) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(14, COALESCE((SELECT FullPath FROM SoloDBDirectoryHeader WHERE Id = NEW.DirectoryId), SOLO_FS_DELETING_PATH(NEW.DirectoryId, 1)), NEW.Key, OLD.Value, NEW.Value, 2) AS message) WHERE SOLO_FS_SHOULD_HANDLE(14) = 1; END;
CREATE TRIGGER IF NOT EXISTS SoloDBEvents_SoloDBDirectoryMetadata_AFTER_UPDATE AFTER UPDATE ON SoloDBDirectoryMetadata FOR EACH ROW WHEN SOLO_FS_SHOULD_HANDLE(15) = 1 BEGIN SELECT CASE WHEN message IS NULL THEN NULL ELSE RAISE(ABORT, message) END FROM (SELECT SOLO_FS_METADATA(15, COALESCE((SELECT FullPath FROM SoloDBDirectoryHeader WHERE Id = NEW.DirectoryId), SOLO_FS_DELETING_PATH(NEW.DirectoryId, 1)), NEW.Key, OLD.Value, NEW.Value, 2) AS message) WHERE SOLO_FS_SHOULD_HANDLE(15) = 1; END;
"""
    |]
    let definitions = definitionsByTable |> Array.map snd |> String.concat "\n"

    let forExistingTables (connection: NativeSqliteConnection) =
        // Collection-only legacy schemas are admitted by initialization. Install
        // row triggers for the filesystem tables actually present in that schema.
        let builder = StringBuilder()
        let mutable statement = connection.OpenStatement("SELECT name FROM sqlite_schema WHERE type='table' AND name IN ('SoloDBFileHeader','SoloDBDirectoryHeader','SoloDBFileMetadata','SoloDBDirectoryMetadata')")
        try
            while statement.Step() do
                let table = statement.Row.GetString(0)
                for name, body in definitionsByTable do
                    if name = table then builder.AppendLine(body) |> ignore
            statement.Dispose()
            builder.ToString()
        with error -> statement.Abort(error); reraise()
